<div class="section-heading"><div><span class="eyebrow"><?= e($p['status']) ?></span><h1>Pedido #<?= e($p['id']) ?><span class="accent">.</span></h1><p><?= e($p['cliente']) ?> · <?= e(date('d/m/Y H:i',strtotime($p['created_at']))) ?></p></div><a class="btn quiet" href="<?= e(url($currentUser['perfil']==='admin'?'admin/pedidos':'orders')) ?>">Voltar aos pedidos</a></div><div class="table-wrap"><table><thead><tr><th>Jogo</th><th>Plataforma</th><th>Quantidade</th><th>Preço na compra</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($items as $i): ?><tr><td><?= e($i['titulo']) ?></td><td><?= e($i['plataforma']) ?></td><td><?= e($i['quantidade']) ?></td><td><?= money($i['preco_unitario']) ?></td><td><?= money(App\Core\Validation::decimal(App\Core\Validation::money($i['preco_unitario'])*(int)$i['quantidade'])) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="order-total"><strong>Total: <?= money($p['total']) ?></strong><?php if ($currentUser['perfil']==='cliente' && in_array($p['status'],['rascunho','confirmado'],true)): ?><form data-confirm="Cancelar este pedido?" method="post" action="<?= e(url('order/cancel')) ?>"><?= csrfField() ?><input type="hidden" name="id" value="<?= e($p['id']) ?>"><button class="btn danger">Cancelar pedido</button></form><?php endif; ?></div>
